select ac_cargar_unidad($ac${"slug":"digital-1","rama":"digital","orden":1,"nivel":1,"titulo_es":"La huella de lo digital","bajada_es":"La nube no está en el cielo: son cables, edificios llenos de computadoras y millones de dispositivos. Cuánto pesa lo digital y qué hábitos importan de verdad.","objetivos_es":["Describir la infraestructura física que sostiene internet","Dimensionar el consumo de energía de centros de datos, redes y dispositivos","Explicar por qué la mayor huella de los dispositivos está en su fabricación","Reconocer los riesgos y el valor de la basura electrónica","Distinguir los hábitos digitales de mucho y de poco impacto"],"repasa":["tronco-2","tronco-3"],"requiere_tronco":1,"fuentes":["iea-datacenters","iea-streaming","ewaste-monitor","carbon-brief"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"digital-1.s1","orden":1,"tipo":"leccion","titulo_es":"Internet es física","bajada_es":"Cables submarinos, centros de datos, antenas y dispositivos: lo que hay detrás de un mensaje.","minutos":9,"pasos":[{"slug":"digital-1.s1.p1","orden":1,"grupo":"digital-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La nube tiene cables","cuerpo":["Cuando mandamos un mensaje o miramos un video, los datos viajan por una infraestructura física enorme: el dispositivo se conecta por wifi o por la red móvil a una antena o un router; de ahí, por cables de fibra óptica, llegan a centros de datos donde están guardados los contenidos. Entre continentes, casi todo el tráfico de internet viaja por cables submarinos.","Los centros de datos son edificios llenos de servidores —computadoras que funcionan todo el día— que necesitan electricidad para funcionar y para enfriarse."]},"solucion":{}},{"slug":"digital-1.s1.p2","orden":2,"grupo":"digital-1.s1.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el recorrido de un video que mirás en el celular.","items":[{"id":"i1","texto":"El video está guardado en un servidor de un centro de datos"},{"id":"i2","texto":"Viaja por cables de fibra óptica"},{"id":"i3","texto":"Llega a la antena o al router de tu casa"},{"id":"i4","texto":"Se transmite por wifi o red móvil a tu celular"},{"id":"i5","texto":"Tu celular lo muestra en la pantalla"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cinco eslabones físicos, cada uno con su consumo de energía."}},{"slug":"digital-1.s1.p3","orden":3,"grupo":"digital-1.s1.p3","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada parte de la infraestructura con lo que hace.","izquierda":[{"id":"a1","texto":"Centro de datos"},{"id":"a2","texto":"Cable submarino"},{"id":"a3","texto":"Antena de telefonía"},{"id":"a4","texto":"Router"}],"derecha":[{"id":"b1","texto":"Guarda y procesa la información"},{"id":"b2","texto":"Conecta continentes"},{"id":"b3","texto":"Conecta los celulares a la red"},{"id":"b4","texto":"Distribuye internet dentro de una casa"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"La \"nube\" es un nombre lindo para una infraestructura muy concreta."}},{"slug":"digital-1.s1.p4","orden":4,"grupo":"digital-1.s1.p4","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La nube es un espacio virtual que no usa recursos físicos.","razones":[{"id":"r1","texto":"Porque son centros de datos reales que usan energía y materiales"},{"id":"r2","texto":"Porque los datos flotan en el aire"},{"id":"r3","texto":"Porque la nube funciona con energía solar gratis siempre"}]},"solucion":{"valor":false,"explicacion":"La nube son centros de datos reales, con miles de servidores que usan electricidad, agua para enfriamiento y materiales para fabricarse.","clave":["r1"]}},{"slug":"digital-1.s1.p5","orden":5,"grupo":"digital-1.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las tres partes de la huella digital","cuerpo":["La huella de lo digital tiene tres grandes partes: los dispositivos (celulares, computadoras, televisores, consolas), las redes que transmiten los datos, y los centros de datos que los guardan y procesan.","De las tres, la que más pesa para una persona suele ser la fabricación de sus propios dispositivos, como vas a ver en esta unidad."]},"solucion":{}},{"slug":"digital-1.s1.p6","orden":6,"grupo":"digital-1.s1.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿A qué parte de la huella digital pertenece cada cosa?","grupos":[{"id":"g1","nombre":"Dispositivos"},{"id":"g2","nombre":"Redes"},{"id":"g3","nombre":"Centros de datos"}],"items":[{"id":"i1","texto":"Tu celular"},{"id":"i2","texto":"La antena de telefonía"},{"id":"i3","texto":"Los servidores de una plataforma de video"},{"id":"i4","texto":"La notebook"},{"id":"i5","texto":"La fibra óptica del barrio"},{"id":"i6","texto":"El almacenamiento de tus fotos en la nube"},{"id":"i7","texto":"El televisor inteligente"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g1"},"explicacion":"Tres partes con impactos distintos. Saber cuál pesa más ordena las decisiones."}},{"slug":"digital-1.s1.p7","orden":7,"grupo":"digital-1.s1.p7","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un centro de datos necesita tanta electricidad.","items":[{"id":"i1","texto":"Miles de servidores funcionan las 24 horas"},{"id":"i2","texto":"Consumen electricidad y generan mucho calor"},{"id":"i3","texto":"Hace falta enfriarlos constantemente"},{"id":"i4","texto":"El enfriamiento suma todavía más consumo"},{"id":"i5","texto":"Los servidores se apagan de noche para ahorrar"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Energía para calcular y energía para enfriar: las dos grandes cuentas de un centro de datos."}},{"slug":"digital-1.s1.p8","orden":8,"grupo":"digital-1.s1.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué recursos usa un centro de datos? Marcá todos.","opciones":[{"id":"o1","texto":"Electricidad"},{"id":"o2","texto":"Agua para refrigeración, en muchos casos"},{"id":"o3","texto":"Materiales para fabricar servidores"},{"id":"o4","texto":"Terreno para el edificio"},{"id":"o5","texto":"Ningún recurso, porque es virtual"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Lo digital tiene una base muy material, aunque no se vea."}},{"slug":"digital-1.s1.p9","orden":9,"grupo":"digital-1.s1.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué casi todo el tráfico de internet entre continentes viaja por cables submarinos y no por satélites?","opciones":[{"id":"o1","texto":"Porque transmiten muchos más datos"},{"id":"o2","texto":"Porque los satélites no pueden transmitir ningún dato"},{"id":"o3","texto":"Porque los cables no usan energía"},{"id":"o4","texto":"Porque el agua del mar acelera los datos"}]},"solucion":{"clave":["o1"],"explicacion":"La fibra óptica submarina tiene una capacidad enorme. Los satélites sirven, sobre todo, donde no llegan los cables.","por_opcion":{"o3":"Usan energía, pero transmiten enormes volúmenes con menos demora que los satélites."}}},{"slug":"digital-1.s1.p10","orden":10,"grupo":"digital-1.s1.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los datos viajan por cables de fibra óptica."},{"id":"s2","texto":"La nube no tiene impacto ambiental porque es invisible."},{"id":"s3","texto":"Los centros de datos necesitan refrigeración."},{"id":"s4","texto":"Los satélites llevan casi todo el tráfico entre continentes."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo digital no es inmaterial: tiene cables, edificios y aparatos.","por_opcion":{"s2":"Son centros de datos físicos que usan energía, agua y materiales.","s4":"Casi todo viaja por cables submarinos."}}},{"slug":"digital-1.s1.p11","orden":11,"grupo":"digital-1.s1.p11","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La nube está formada por centros de {{0}}; entre continentes, internet viaja por cables {{1}}.","banco":[{"id":"w1","texto":"datos"},{"id":"w2","texto":"submarinos"},{"id":"w3","texto":"nubes"},{"id":"w4","texto":"aéreos"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La infraestructura física de internet, en una línea."}},{"slug":"digital-1.s1.p12","orden":12,"grupo":"digital-1.s1.p12","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos eslabones según su distancia a vos, del más cercano al más lejano.","items":[{"id":"i1","texto":"Tu celular"},{"id":"i2","texto":"El router de tu casa"},{"id":"i3","texto":"La central del proveedor de internet"},{"id":"i4","texto":"El centro de datos"}],"extremos":["Más cercano","Más lejano"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada clic recorre una cadena física que puede cruzar el planeta.","valores":{"i1":"en tu mano","i2":"a pocos metros","i3":"en tu ciudad","i4":"puede estar en otro país"}}}]},{"slug":"digital-1.s2","orden":2,"tipo":"leccion","titulo_es":"Cuánta energía usa lo digital","bajada_es":"Centros de datos, redes y streaming: los números reales y los mitos.","minutos":11,"pasos":[{"slug":"digital-1.s2.p1","orden":1,"grupo":"digital-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los números globales","cuerpo":["Según la Agencia Internacional de Energía, en 2024 los centros de datos del mundo consumieron alrededor de 415 teravatios-hora de electricidad, cerca del 1,5 % de la electricidad mundial. Las redes de datos consumen una cantidad parecida. Y el consumo de los centros de datos está creciendo rápido, sobre todo por la inteligencia artificial.","Para comparar: Argentina entera consume alrededor de 140 teravatios-hora por año."],"destacado":{"valor":"≈ 1,5 %","texto":"de la electricidad mundial consumieron los centros de datos en 2024, según la Agencia Internacional de Energía."}},"solucion":{}},{"slug":"digital-1.s2.p2","orden":2,"grupo":"digital-1.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los centros de datos del mundo consumieron unos 415 TWh en 2024 y Argentina consume unos 140 TWh de electricidad por año. ¿Cuántas veces el consumo de Argentina es el de los centros de datos? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3,"tolerancia":0.1,"explicacion":"415 ÷ 140 ≈ 3 veces. Una forma de dimensionar un número enorme comparándolo con algo conocido."}},{"slug":"digital-1.s2.p2.v2","orden":2,"grupo":"digital-1.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los centros de datos del mundo consumieron unos 415 TWh en 2024 y Chile consume unos 85 TWh de electricidad por año. ¿Cuántas veces el consumo de Chile es el de los centros de datos? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":4.9,"tolerancia":0.1,"explicacion":"415 ÷ 85 ≈ 4,9 veces. Una forma de dimensionar un número enorme comparándolo con algo conocido."}},{"slug":"digital-1.s2.p2.v3","orden":2,"grupo":"digital-1.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Los centros de datos del mundo consumieron unos 415 TWh en 2024 y Uruguay consume unos 12 TWh de electricidad por año. ¿Cuántas veces el consumo de Uruguay es el de los centros de datos? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":34.6,"tolerancia":0.1,"explicacion":"415 ÷ 12 ≈ 34,6 veces. Una forma de dimensionar un número enorme comparándolo con algo conocido."}},{"slug":"digital-1.s2.p3","orden":3,"grupo":"digital-1.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El streaming","cuerpo":["Hubo titulares que decían que mirar media hora de video emitía kilos de CO₂. Eran exageraciones basadas en cálculos equivocados. La Agencia Internacional de Energía estimó que una hora de video en streaming usa alrededor de 0,08 kWh en todo el recorrido —centro de datos, redes y dispositivo— y emite unos 36 gramos de CO₂ con la mezcla eléctrica promedio del mundo.","Es poco por hora, aunque, multiplicado por miles de millones de horas, suma. Y el dispositivo que se usa pesa: un televisor grande consume mucho más que un celular."]},"solucion":{}},{"slug":"digital-1.s2.p4","orden":4,"grupo":"digital-1.s2.p4","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos gramos de CO₂ emite una hora de streaming de video, según la Agencia Internacional de Energía (promedio mundial).","min":1,"max":5000,"paso":1,"unidad":"g","escala":"log"},"solucion":{"valor":36,"banda":"log","explicacion":"Alrededor de 36 gramos. Los titulares que hablaban de kilos por media hora eran exagerados."}},{"slug":"digital-1.s2.p5","orden":5,"grupo":"digital-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona mira 2 horas de video por día. Con 36 g de CO₂ por hora, ¿cuántos kg emite en un año de 365 días? Redondeá a un decimal.","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":26.3,"tolerancia":0.2,"explicacion":"2 × 36 × 365 = 26.280 g ≈ 26,3 kg por año. Comparalo con los ~ 500 kg por año de ir 12 km diarios solo en auto."}},{"slug":"digital-1.s2.p5.v2","orden":5,"grupo":"digital-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona mira 3 horas de video por día. Con 36 g de CO₂ por hora, ¿cuántos kg emite en un año de 365 días? Redondeá a un decimal.","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":39.4,"tolerancia":0.2,"explicacion":"3 × 36 × 365 = 39.420 g ≈ 39,4 kg por año. Comparalo con los ~ 500 kg por año de ir 12 km diarios solo en auto."}},{"slug":"digital-1.s2.p5.v3","orden":5,"grupo":"digital-1.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona mira 4 horas de video por día. Con 36 g de CO₂ por hora, ¿cuántos kg emite en un año de 365 días? Redondeá a un decimal.","unidad":"kg de CO₂","decimales":1},"solucion":{"valor":52.6,"tolerancia":0.2,"explicacion":"4 × 36 × 365 = 52.560 g ≈ 52,6 kg por año. Comparalo con los ~ 500 kg por año de ir 12 km diarios solo en auto."}},{"slug":"digital-1.s2.p6","orden":6,"grupo":"digital-1.s2.p6","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas actividades por emisiones típicas, de más a menos.","items":[{"id":"i1","texto":"Un vuelo de 1.000 km ida y vuelta"},{"id":"i2","texto":"Un año yendo 12 km diarios solo en auto"},{"id":"i3","texto":"Un año mirando 2 horas de video por día"},{"id":"i4","texto":"Mandar un mail"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los órdenes de magnitud del tronco: lo digital suma, pero pesa mucho menos que volar o manejar.","valores":{"i1":"≈ 500 kg de CO₂e","i2":"≈ 500 kg de CO₂e","i3":"≈ 26 kg de CO₂","i4":"unos pocos gramos"}}},{"slug":"digital-1.s2.p7","orden":7,"grupo":"digital-1.s2.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Mirar media hora de video emite varios kilos de CO₂.","razones":[{"id":"r1","texto":"Porque esos cálculos fueron corregidos: son decenas de gramos por hora"},{"id":"r2","texto":"Porque el video no usa electricidad"},{"id":"r3","texto":"Porque el video emite toneladas por minuto"}]},"solucion":{"valor":false,"explicacion":"Era un cálculo exagerado. Según la Agencia Internacional de Energía, una hora emite unos 36 gramos con la mezcla eléctrica promedio del mundo.","clave":["r1"]}},{"slug":"digital-1.s2.p8","orden":8,"grupo":"digital-1.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La inteligencia artificial","cuerpo":["Entrenar y usar grandes modelos de inteligencia artificial requiere muchísimo cálculo, y por eso mucha electricidad. La Agencia Internacional de Energía proyecta que el consumo de los centros de datos podría más que duplicarse hacia 2030, impulsado en buena parte por la inteligencia artificial.","Que ese crecimiento se cubra con energía limpia o con combustibles fósiles es una de las grandes preguntas energéticas de esta década."]},"solucion":{}},{"slug":"digital-1.s2.p9","orden":9,"grupo":"digital-1.s2.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el crecimiento de la inteligencia artificial afecta al sistema eléctrico.","items":[{"id":"i1","texto":"Se usan cada vez más modelos de inteligencia artificial"},{"id":"i2","texto":"Hacen falta más centros de datos y más cálculo"},{"id":"i3","texto":"Aumenta la demanda de electricidad"},{"id":"i4","texto":"Hay que generar más electricidad"},{"id":"i5","texto":"Las emisiones dependen de si esa electricidad es limpia"},{"id":"i6","texto":"La inteligencia artificial produce su propia energía"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La huella de la IA depende de cuánto crece y de cómo se genera su electricidad."}},{"slug":"digital-1.s2.p10","orden":10,"grupo":"digital-1.s2.p10","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué parte de la huella digital pesa más en cada caso?","grupos":[{"id":"g1","nombre":"La fabricación del dispositivo"},{"id":"g2","nombre":"La electricidad de uso"}],"items":[{"id":"i1","texto":"Un celular usado dos años"},{"id":"i2","texto":"Un televisor grande encendido muchas horas"},{"id":"i3","texto":"Una notebook nueva"},{"id":"i4","texto":"Una consola de juegos siempre encendida"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Los aparatos chicos tienen su huella en la fabricación; los grandes que están siempre encendidos, en el uso."}},{"slug":"digital-1.s2.p11","orden":11,"grupo":"digital-1.s2.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada número con lo que mide.","izquierda":[{"id":"a1","texto":"≈ 415 TWh"},{"id":"a2","texto":"≈ 140 TWh"},{"id":"a3","texto":"≈ 36 g"},{"id":"a4","texto":"≈ 1,5 %"}],"derecha":[{"id":"b1","texto":"Consumo de los centros de datos del mundo en 2024"},{"id":"b2","texto":"Consumo eléctrico anual de Argentina"},{"id":"b3","texto":"CO₂ de una hora de video en streaming"},{"id":"b4","texto":"Parte de la electricidad mundial que usan los centros de datos"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro números para ubicar lo digital en su escala real."}},{"slug":"digital-1.s2.p12","orden":12,"grupo":"digital-1.s2.p12","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Mirando la misma serie una hora, ¿qué aparato hace que el consumo sea mayor?","opciones":[{"id":"o1","texto":"Un televisor grande"},{"id":"o2","texto":"Un celular"},{"id":"o3","texto":"Una tablet chica"},{"id":"o4","texto":"Un reloj inteligente"}]},"solucion":{"clave":["o1"],"explicacion":"El dispositivo pesa en el consumo del streaming: un televisor grande consume muchas veces más que un celular.","por_opcion":{"o3":"Las pantallas chicas consumen mucho menos que un televisor grande."}}},{"slug":"digital-1.s2.p13","orden":13,"grupo":"digital-1.s2.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este titular y marcá lo exagerado o equivocado.","segmentos":[{"id":"s1","texto":"Los centros de datos usan alrededor del 1,5 % de la electricidad mundial."},{"id":"s2","texto":"Mirar una serie contamina más que un viaje en avión."},{"id":"s3","texto":"El consumo de los centros de datos crece por la inteligencia artificial."},{"id":"s4","texto":"Lo digital no tiene ningún impacto ambiental."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Ni exagerar ni ignorar: la clave es dimensionar con datos.","por_opcion":{"s2":"Un vuelo emite cientos de kilos; una hora de video, unos 36 gramos.","s4":"Tiene impacto, aunque cada actividad individual sea chica."}}},{"slug":"digital-1.s2.p14","orden":14,"grupo":"digital-1.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los centros de datos usan alrededor del {{0}} % de la electricidad mundial; una hora de video emite unos {{1}} gramos de CO₂.","banco":[{"id":"w1","texto":"1,5"},{"id":"w2","texto":"36"},{"id":"w3","texto":"15"},{"id":"w4","texto":"3.600"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos números para dimensionar lo digital sin exagerar."}}]},{"slug":"digital-1.s3","orden":3,"tipo":"leccion","titulo_es":"Dispositivos: la huella está en fabricarlos","bajada_es":"Por qué el celular que ya tenés es el más sustentable, y cuántos aparatos hay en una casa.","minutos":11,"pasos":[{"slug":"digital-1.s3.p1","orden":1,"grupo":"digital-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Muchos aparatos por casa","cuerpo":["Hoy una casa típica puede tener varios celulares, una o dos computadoras, televisores, tablets, consolas, parlantes inteligentes, relojes y routers. Cada uno se fabricó con minerales, energía y agua, y tiene su huella antes de encenderse por primera vez.","Como viste en la rama de Consumo, en celulares y notebooks la mayor parte de la huella de carbono de toda su vida está en la fabricación."]},"solucion":{}},{"slug":"digital-1.s3.p2","orden":2,"grupo":"digital-1.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa hay 4 celulares. Si fabricar cada uno emite unos 70 kg de CO₂e, ¿cuántos kg suma la fabricación de todos?","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":280,"tolerancia":5.6000000000000005,"explicacion":"4 × 70 = 280 kg CO₂e solo en fabricar los celulares. Por eso cambiarlos seguido multiplica la huella."}},{"slug":"digital-1.s3.p2.v2","orden":2,"grupo":"digital-1.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa hay 3 celulares. Si fabricar cada uno emite unos 60 kg de CO₂e, ¿cuántos kg suma la fabricación de todos?","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":180,"tolerancia":3.6,"explicacion":"3 × 60 = 180 kg CO₂e solo en fabricar los celulares. Por eso cambiarlos seguido multiplica la huella."}},{"slug":"digital-1.s3.p2.v3","orden":2,"grupo":"digital-1.s3.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa hay 5 celulares. Si fabricar cada uno emite unos 80 kg de CO₂e, ¿cuántos kg suma la fabricación de todos?","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":400,"tolerancia":8,"explicacion":"5 × 80 = 400 kg CO₂e solo en fabricar los celulares. Por eso cambiarlos seguido multiplica la huella."}},{"slug":"digital-1.s3.p3","orden":3,"grupo":"digital-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuánto dura un celular","cuerpo":["Muchas personas cambian el celular cada dos o tres años, aunque podría durar más. Pasar de dos a cuatro años de uso reduce casi a la mitad la huella de fabricación por año. Cambiar la batería, usar funda y protector, y mantener el sistema actualizado ayudan a estirar su vida."]},"solucion":{}},{"slug":"digital-1.s3.p4","orden":4,"grupo":"digital-1.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fabricar un celular emite 70 kg de CO₂e. ¿Cuántos kg por año de uso se ahorran si se usa 4 años en lugar de 2?","unidad":"kg por año","decimales":1},"solucion":{"valor":17.5,"tolerancia":0.35000000000000003,"explicacion":"Con 2 años: 70 ÷ 2 = 35 kg por año. Con 4 años: 70 ÷ 4 = 17.5. Se ahorran 17.5 kg por año."}},{"slug":"digital-1.s3.p4.v2","orden":4,"grupo":"digital-1.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fabricar un celular emite 60 kg de CO₂e. ¿Cuántos kg por año de uso se ahorran si se usa 4 años en lugar de 2?","unidad":"kg por año","decimales":1},"solucion":{"valor":15,"tolerancia":0.3,"explicacion":"Con 2 años: 60 ÷ 2 = 30 kg por año. Con 4 años: 60 ÷ 4 = 15. Se ahorran 15 kg por año."}},{"slug":"digital-1.s3.p4.v3","orden":4,"grupo":"digital-1.s3.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Fabricar un celular emite 80 kg de CO₂e. ¿Cuántos kg por año de uso se ahorran si se usa 4 años en lugar de 2?","unidad":"kg por año","decimales":1},"solucion":{"valor":20,"tolerancia":0.4,"explicacion":"Con 2 años: 80 ÷ 2 = 40 kg por año. Con 4 años: 80 ÷ 4 = 20. Se ahorran 20 kg por año."}},{"slug":"digital-1.s3.p5","orden":5,"grupo":"digital-1.s3.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Comprar un celular nuevo más eficiente reduce la huella porque consume menos batería.","razones":[{"id":"r1","texto":"Porque la fabricación pesa mucho más que la carga"},{"id":"r2","texto":"Porque los celulares nuevos no se fabrican"},{"id":"r3","texto":"Porque la batería es la parte más contaminante del uso"}]},"solucion":{"valor":false,"explicacion":"El ahorro en la carga es mínimo comparado con la huella de fabricar uno nuevo. Para los celulares, lo más sustentable es usar más tiempo el que ya se tiene.","clave":["r1"]}},{"slug":"digital-1.s3.p6","orden":6,"grupo":"digital-1.s3.p6","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué alarga la vida de un dispositivo? Marcá todo.","opciones":[{"id":"o1","texto":"Funda y protector de pantalla"},{"id":"o2","texto":"Cambiar la batería cuando se gasta"},{"id":"o3","texto":"Mantener el sistema actualizado"},{"id":"o4","texto":"Liberar espacio en lugar de cambiar el aparato"},{"id":"o5","texto":"Cambiarlo cuando sale un modelo nuevo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cuidar, mantener y reparar son las mejores decisiones digitales."}},{"slug":"digital-1.s3.p7","orden":7,"grupo":"digital-1.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Segunda vida","cuerpo":["Cuando un celular o una computadora ya no sirve para quien lo tenía, muchas veces sirve para otra persona: un familiar, una escuela, una organización. También existen equipos reacondicionados, revisados y con garantía, que cuestan menos y evitan fabricar uno nuevo."]},"solucion":{}},{"slug":"digital-1.s3.p8","orden":8,"grupo":"digital-1.s3.p8","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená qué conviene hacer con un celular que ya no usás, de la mejor a la última opción.","items":[{"id":"i1","texto":"Seguir usándolo si funciona"},{"id":"i2","texto":"Dárselo a alguien que lo necesite"},{"id":"i3","texto":"Venderlo o entregarlo para reacondicionar"},{"id":"i4","texto":"Llevarlo a un punto de reciclaje de electrónicos"}],"extremos":["Mejor","Última opción"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La jerarquía de siempre: usar, reutilizar y, al final, reciclar."}},{"slug":"digital-1.s3.p9","orden":9,"grupo":"digital-1.s3.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción reduce la huella de los dispositivos de una casa o la aumenta?","grupos":[{"id":"g1","nombre":"La reduce"},{"id":"g2","nombre":"La aumenta"}],"items":[{"id":"i1","texto":"Compartir una tablet entre hermanos"},{"id":"i2","texto":"Un celular nuevo cada año para cada integrante"},{"id":"i3","texto":"Comprar una notebook reacondicionada"},{"id":"i4","texto":"Guardar celulares viejos en un cajón para siempre"},{"id":"i5","texto":"Arreglar el puerto de carga"},{"id":"i6","texto":"Tirar los aparatos rotos con la basura común"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Menos aparatos, más años de uso y un buen destino final."}},{"slug":"digital-1.s3.p10","orden":10,"grupo":"digital-1.s3.p10","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tu celular de tres años funciona bien pero la batería dura poco. ¿Qué conviene?","opciones":[{"id":"o1","texto":"Cambiar la batería"},{"id":"o2","texto":"Comprar uno nuevo del mismo modelo"},{"id":"o3","texto":"Cargarlo menos veces para cuidarlo"},{"id":"o4","texto":"Guardarlo y comprar uno nuevo"}]},"solucion":{"clave":["o1"],"explicacion":"Una batería nueva cuesta una fracción del aparato y puede darle dos o tres años más de vida.","por_opcion":{"o3":"No resuelve que la batería esté gastada."}}},{"slug":"digital-1.s3.p11","orden":11,"grupo":"digital-1.s3.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Usar el celular más años reduce su huella anual."},{"id":"s2","texto":"Guardar el celular viejo en un cajón es tan bueno como reciclarlo."},{"id":"s3","texto":"Los equipos reacondicionados evitan fabricar uno nuevo."},{"id":"s4","texto":"Cambiar la batería no vale la pena, conviene un celular nuevo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La decisión digital más importante es cuánto dura cada aparato.","por_opcion":{"s2":"En un cajón no sirve a nadie: conviene darlo, venderlo o reciclarlo.","s4":"Cambiar la batería alarga la vida útil con una fracción del impacto."}}},{"slug":"digital-1.s3.p12","orden":12,"grupo":"digital-1.s3.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En un celular, la mayor parte de la huella está en su {{0}}; usarlo el {{1}} de años reduce casi a la mitad su huella anual.","banco":[{"id":"w1","texto":"fabricación"},{"id":"w2","texto":"doble"},{"id":"w3","texto":"carga"},{"id":"w4","texto":"triple"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La idea central sobre la huella de los dispositivos."}},{"slug":"digital-1.s3.p13","orden":13,"grupo":"digital-1.s3.p13","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos años conviene usar, como mínimo, un celular para que su huella de fabricación por año sea la mitad que si se usara 2 años.","min":1,"max":10,"paso":1,"unidad":"años","escala":"lineal"},"solucion":{"valor":4,"banda":"lineal","explicacion":"Cuatro años: la huella de fabricación se reparte entre el doble de años. Y cada año más la sigue diluyendo."}}]},{"slug":"digital-1.s4","orden":4,"tipo":"leccion","titulo_es":"La basura electrónica","bajada_es":"Metales valiosos y sustancias peligrosas: qué tiene un aparato viejo y adónde tiene que ir.","minutos":11,"pasos":[{"slug":"digital-1.s4.p1","orden":1,"grupo":"digital-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El residuo que más crece","cuerpo":["Los residuos de aparatos eléctricos y electrónicos (RAEE) son todo lo que tiene enchufe o pilas y se descarta: celulares, computadoras, cargadores, electrodomésticos, juguetes con pilas. Según el Monitor Mundial de Residuos Electrónicos, en 2022 se generaron unos 62 millones de toneladas en el mundo, alrededor de 7,8 kg por persona, y solo un 22 % se recolectó y recicló de forma documentada.","Es uno de los tipos de residuos que más rápido crece."],"destacado":{"valor":"≈ 22 %","texto":"de la basura electrónica del mundo se recolectó y recicló de forma documentada en 2022."}},"solucion":{}},{"slug":"digital-1.s4.p2","orden":2,"grupo":"digital-1.s4.p2","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos kilos de basura electrónica por persona se generaron en el mundo en 2022.","min":0.1,"max":100,"paso":1,"unidad":"kg","escala":"log"},"solucion":{"valor":7.8,"banda":"log","explicacion":"Alrededor de 7,8 kg por persona, según el Monitor Mundial de Residuos Electrónicos. Mucho más en los países de altos ingresos."}},{"slug":"digital-1.s4.p3","orden":3,"grupo":"digital-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo valioso y lo peligroso","cuerpo":["Un aparato electrónico tiene metales valiosos —cobre, oro, plata, paladio— que se pueden recuperar, y también sustancias peligrosas, como plomo, mercurio, cadmio y retardantes de llama. Si se tira con la basura común o se quema, esas sustancias pueden contaminar el suelo, el agua y el aire, y dañar la salud de quienes manipulan los residuos.","Las baterías de litio, además, pueden incendiarse si se aplastan en un camión o en un relleno."]},"solucion":{}},{"slug":"digital-1.s4.p4","orden":4,"grupo":"digital-1.s4.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un material valioso para recuperar o una sustancia peligrosa?","grupos":[{"id":"g1","nombre":"Valioso"},{"id":"g2","nombre":"Peligroso"}],"items":[{"id":"i1","texto":"Cobre"},{"id":"i2","texto":"Plomo"},{"id":"i3","texto":"Oro"},{"id":"i4","texto":"Mercurio"},{"id":"i5","texto":"Plata"},{"id":"i6","texto":"Cadmio"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La basura electrónica es a la vez un tesoro y un riesgo. Todo depende de adónde va."}},{"slug":"digital-1.s4.p5","orden":5,"grupo":"digital-1.s4.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de qué puede pasar si una batería de litio va a la basura común.","items":[{"id":"i1","texto":"Se tira una batería de litio con la basura común"},{"id":"i2","texto":"El camión compactador la aplasta"},{"id":"i3","texto":"La batería se daña y se calienta"},{"id":"i4","texto":"Puede iniciar un incendio en el camión o en el relleno"},{"id":"i5","texto":"La batería se descarga sola y desaparece"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las baterías de litio nunca van a la basura común: tienen que ir a puntos de recolección."}},{"slug":"digital-1.s4.p6","orden":6,"grupo":"digital-1.s4.p6","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un celular viejo se puede tirar con la basura común sin problema.","razones":[{"id":"r1","texto":"Porque tiene sustancias peligrosas y metales recuperables"},{"id":"r2","texto":"Porque los celulares se descomponen en semanas"},{"id":"r3","texto":"Porque la basura común separa los celulares automáticamente"}]},"solucion":{"valor":false,"explicacion":"Tiene sustancias peligrosas y una batería que puede incendiarse, además de metales valiosos que se pierden. Tiene que ir a un punto de recolección de electrónicos.","clave":["r1"]}},{"slug":"digital-1.s4.p7","orden":7,"grupo":"digital-1.s4.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si se generaron 62 millones de toneladas de basura electrónica y se recicló de forma documentada el 22 %, ¿cuántos millones de toneladas se reciclaron? Redondeá a un decimal.","unidad":"millones de toneladas","decimales":1},"solucion":{"valor":13.6,"tolerancia":0.1,"explicacion":"62 × 22 ÷ 100 ≈ 13,6 millones de toneladas. El resto, más de 48 millones, no tuvo un destino documentado."}},{"slug":"digital-1.s4.p8","orden":8,"grupo":"digital-1.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Adónde llevarla","cuerpo":["Muchos municipios tienen puntos verdes o campañas de recolección de electrónicos y pilas. Algunos comercios y fabricantes reciben aparatos viejos. Antes de entregar un celular o una computadora, conviene borrar los datos personales.","En varios lugares, cooperativas y empresas especializadas desarman los aparatos, recuperan los metales y tratan de forma segura las sustancias peligrosas."]},"solucion":{}},{"slug":"digital-1.s4.p9","orden":9,"grupo":"digital-1.s4.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para desprenderte bien de una notebook vieja.","items":[{"id":"i1","texto":"Evaluar si alguien puede seguir usándola"},{"id":"i2","texto":"Hacer una copia de tus archivos"},{"id":"i3","texto":"Borrar tus datos personales"},{"id":"i4","texto":"Entregarla para reutilizar o en un punto de recolección de electrónicos"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero reutilizar; si no se puede, reciclar bien y cuidando tus datos."}},{"slug":"digital-1.s4.p10","orden":10,"grupo":"digital-1.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué cosas son residuos electrónicos que no van a la basura común? Marcá todas.","opciones":[{"id":"o1","texto":"Cargadores viejos"},{"id":"o2","texto":"Pilas y baterías"},{"id":"o3","texto":"Auriculares rotos"},{"id":"o4","texto":"Un secador de pelo roto"},{"id":"o5","texto":"Una caja de cartón del celular"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Todo lo que tuvo enchufe o pilas es RAEE. La caja de cartón va con los reciclables de papel."}},{"slug":"digital-1.s4.p11","orden":11,"grupo":"digital-1.s4.p11","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos destinos para un celular roto, del mejor al peor.","items":[{"id":"i1","texto":"Repararlo y seguir usándolo"},{"id":"i2","texto":"Llevarlo a un punto de recolección de electrónicos"},{"id":"i3","texto":"Guardarlo años en un cajón"},{"id":"i4","texto":"Tirarlo con la basura común"}],"extremos":["Mejor","Peor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Reparar primero; si no, reciclar bien. El cajón y la basura desperdician materiales valiosos.","valores":{"i1":"el mejor","i2":"bueno","i3":"malo","i4":"muy malo"}}},{"slug":"digital-1.s4.p12","orden":12,"grupo":"digital-1.s4.p12","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Antes de entregar un celular para reciclar o donar, conviene borrar tus datos personales.","razones":[{"id":"r1","texto":"Porque así se protege tu información personal"},{"id":"r2","texto":"Porque los datos hacen más pesado el celular"},{"id":"r3","texto":"Porque sin borrar los datos no se puede reciclar el cobre"}]},"solucion":{"valor":true,"explicacion":"Así se protege tu información. Se hace una copia de lo que quieras conservar y se restablece el equipo de fábrica.","clave":["r1"]}},{"slug":"digital-1.s4.p13","orden":13,"grupo":"digital-1.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos y marcá los equivocados.","segmentos":[{"id":"s1","texto":"Llevá las pilas a un punto de recolección."},{"id":"s2","texto":"Quemá los cables viejos para sacar el cobre."},{"id":"s3","texto":"Borrá tus datos antes de entregar un celular."},{"id":"s4","texto":"Las baterías de litio van con la basura común."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen destino protege el ambiente, la salud de los trabajadores y tus datos.","por_opcion":{"s2":"Quemar cables libera humos tóxicos: es peligroso y contaminante.","s4":"Pueden incendiarse: van a puntos de recolección."}}},{"slug":"digital-1.s4.p14","orden":14,"grupo":"digital-1.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los residuos de aparatos con enchufe o pilas se llaman {{0}}; solo un {{1}} % de la basura electrónica del mundo se recicla de forma documentada.","banco":[{"id":"w1","texto":"RAEE"},{"id":"w2","texto":"22"},{"id":"w3","texto":"RSU"},{"id":"w4","texto":"80"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos datos clave sobre la basura electrónica."}}]},{"slug":"digital-1.s5","orden":5,"tipo":"leccion","titulo_es":"Hábitos digitales que importan","bajada_es":"Borrar mails, bajar la resolución, apagar el router o conservar el celular: qué pesa y qué casi no.","minutos":11,"pasos":[{"slug":"digital-1.s5.p1","orden":1,"grupo":"digital-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ordenar por impacto","cuerpo":["Hay muchos consejos sobre \"higiene digital\": borrar mails, no guardar fotos repetidas, bajar la calidad del video. Tienen algún efecto, pero chico comparado con otras decisiones. Lo que más pesa en la huella digital de una persona es cuántos aparatos tiene y cuánto le duran, y cuánto tiempo están encendidos los aparatos grandes, como televisores y consolas.","Como en el tronco: primero lo grande, después lo chico."]},"solucion":{}},{"slug":"digital-1.s5.p2","orden":2,"grupo":"digital-1.s5.p2","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos hábitos digitales por su efecto en la huella, de mayor a menor.","items":[{"id":"i1","texto":"Usar el celular 4 años en vez de 2"},{"id":"i2","texto":"Apagar el televisor y la consola cuando no se usan"},{"id":"i3","texto":"Mirar video en calidad estándar en vez de 4K"},{"id":"i4","texto":"Borrar mails viejos"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La duración de los dispositivos pesa mucho más que la limpieza de la bandeja de entrada.","valores":{"i1":"efecto grande","i2":"efecto moderado","i3":"efecto chico","i4":"efecto muy chico"}}},{"slug":"digital-1.s5.p3","orden":3,"grupo":"digital-1.s5.p3","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Borrar todos los mails viejos es una de las acciones más efectivas para el clima.","razones":[{"id":"r1","texto":"Porque su efecto es muy chico comparado con otras acciones"},{"id":"r2","texto":"Porque los mails no se guardan en ningún lado"},{"id":"r3","texto":"Porque borrar mails aumenta las emisiones"}]},"solucion":{"valor":false,"explicacion":"Tiene un efecto muy chico. Usar los dispositivos más años o cambiar un hábito de transporte pesan muchísimo más.","clave":["r1"]}},{"slug":"digital-1.s5.p4","orden":4,"grupo":"digital-1.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El stand-by digital","cuerpo":["Televisores, decodificadores, consolas y parlantes inteligentes pueden consumir energía aunque parezcan apagados. Una consola que queda en modo de encendido rápido puede consumir bastante más que en apagado total. Como viste en la rama de Energía, el stand-by suma a lo largo del año."]},"solucion":{}},{"slug":"digital-1.s5.p5","orden":5,"grupo":"digital-1.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una consola en modo de encendido rápido consume 15 W las 20 horas del día que no se usa. ¿Cuántos kWh usa por año así? Redondeá al entero.","unidad":"kWh","decimales":0},"solucion":{"valor":110,"tolerancia":1,"explicacion":"0,015 kW × 20 h × 365 ≈ 110 kWh por año, sin usarla. Apagarla del todo evita casi todo ese consumo."}},{"slug":"digital-1.s5.p5.v2","orden":5,"grupo":"digital-1.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una consola en modo de encendido rápido consume 10 W las 20 horas del día que no se usa. ¿Cuántos kWh usa por año así? Redondeá al entero.","unidad":"kWh","decimales":0},"solucion":{"valor":73,"tolerancia":1,"explicacion":"0,01 kW × 20 h × 365 ≈ 73 kWh por año, sin usarla. Apagarla del todo evita casi todo ese consumo."}},{"slug":"digital-1.s5.p5.v3","orden":5,"grupo":"digital-1.s5.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una consola en modo de encendido rápido consume 20 W las 20 horas del día que no se usa. ¿Cuántos kWh usa por año así? Redondeá al entero.","unidad":"kWh","decimales":0},"solucion":{"valor":146,"tolerancia":1,"explicacion":"0,02 kW × 20 h × 365 ≈ 146 kWh por año, sin usarla. Apagarla del todo evita casi todo ese consumo."}},{"slug":"digital-1.s5.p6","orden":6,"grupo":"digital-1.s5.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este hábito tiene un efecto grande o chico sobre la huella digital?","grupos":[{"id":"g1","nombre":"Grande"},{"id":"g2","nombre":"Chico"}],"items":[{"id":"i1","texto":"Cambiar el celular cada 4 años en lugar de cada año"},{"id":"i2","texto":"Borrar fotos repetidas de la nube"},{"id":"i3","texto":"No tener un televisor en cada habitación"},{"id":"i4","texto":"Mandar menos mails de \"gracias\""},{"id":"i5","texto":"Comprar una notebook reacondicionada"},{"id":"i6","texto":"Usar el modo oscuro en el celular"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los hábitos chicos no están mal, pero no reemplazan a los grandes."}},{"slug":"digital-1.s5.p7","orden":7,"grupo":"digital-1.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo digital que ahorra","cuerpo":["Lo digital también puede ahorrar mucho: una videollamada en lugar de un vuelo de negocios, trabajar desde casa algunos días en lugar de viajar en auto, una factura electrónica en lugar de una en papel que se imprime y se transporta. En esos casos, la huella digital es muy chica comparada con lo que se evita."]},"solucion":{}},{"slug":"digital-1.s5.p8","orden":8,"grupo":"digital-1.s5.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una reunión presencial requiere un vuelo de ida y vuelta de 1.000 km por tramo (246 g por km). Una videollamada de 2 horas emite unos 100 g. ¿Cuántos kg de CO₂e se ahorran con la videollamada? Redondeá al entero.","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":492,"tolerancia":1,"explicacion":"Vuelo: 2 × 1.000 × 246 = 492.000 g. Menos 100 g de la videollamada: se ahorran unos 492 kg."}},{"slug":"digital-1.s5.p8.v2","orden":8,"grupo":"digital-1.s5.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una reunión presencial requiere un vuelo de ida y vuelta de 700 km por tramo (246 g por km). Una videollamada de 2 horas emite unos 100 g. ¿Cuántos kg de CO₂e se ahorran con la videollamada? Redondeá al entero.","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":344,"tolerancia":1,"explicacion":"Vuelo: 2 × 700 × 246 = 344.400 g. Menos 100 g de la videollamada: se ahorran unos 344 kg."}},{"slug":"digital-1.s5.p8.v3","orden":8,"grupo":"digital-1.s5.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una reunión presencial requiere un vuelo de ida y vuelta de 1.500 km por tramo (246 g por km). Una videollamada de 2 horas emite unos 100 g. ¿Cuántos kg de CO₂e se ahorran con la videollamada? Redondeá al entero.","unidad":"kg CO₂e","decimales":0},"solucion":{"valor":738,"tolerancia":1,"explicacion":"Vuelo: 2 × 1.500 × 246 = 738.000 g. Menos 100 g de la videollamada: se ahorran unos 738 kg."}},{"slug":"digital-1.s5.p9","orden":9,"grupo":"digital-1.s5.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el trabajo remoto algunos días puede bajar emisiones.","items":[{"id":"i1","texto":"Una persona trabaja desde casa dos días por semana"},{"id":"i2","texto":"Deja de viajar en auto esos días"},{"id":"i3","texto":"Ahorra el combustible de esos viajes"},{"id":"i4","texto":"Su huella baja mucho más de lo que suma la videollamada"},{"id":"i5","texto":"La computadora de casa emite más que el auto"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Pero ojo: si trabajar desde casa implica calefaccionar toda la casa todo el día, parte del ahorro se pierde. Siempre hay que mirar el sistema completo."}},{"slug":"digital-1.s5.p10","orden":10,"grupo":"digital-1.s5.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hábitos digitales valen la pena? Marcá todos.","opciones":[{"id":"o1","texto":"Usar los dispositivos el mayor tiempo posible"},{"id":"o2","texto":"Apagar del todo televisores y consolas"},{"id":"o3","texto":"Evitar tener aparatos duplicados que no se usan"},{"id":"o4","texto":"Reemplazar viajes largos por videollamadas cuando se puede"},{"id":"o5","texto":"Comprar un parlante inteligente para cada habitación"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Menos aparatos, más años de uso, menos stand-by y viajes evitados."}},{"slug":"digital-1.s5.p11","orden":11,"grupo":"digital-1.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Mirando lo mismo durante una hora, ¿qué consume más energía?","opciones":[{"id":"o1","texto":"Un televisor de 55 pulgadas"},{"id":"o2","texto":"Un celular"},{"id":"o3","texto":"Una notebook con la pantalla al mínimo"},{"id":"o4","texto":"Un parlante chico con radio"}]},"solucion":{"clave":["o1"],"explicacion":"La pantalla grande es la que más consume. Mirar en el dispositivo más chico que sirva ahorra energía.","por_opcion":{"o3":"Consume más que un celular, pero bastante menos que un televisor grande."}}},{"slug":"digital-1.s5.p12","orden":12,"grupo":"digital-1.s5.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Usar el modo oscuro en el celular es uno de los hábitos digitales de mayor impacto.","razones":[{"id":"r1","texto":"Porque su efecto es mínimo comparado con la vida útil del aparato"},{"id":"r2","texto":"Porque el modo oscuro aumenta mucho las emisiones"},{"id":"r3","texto":"Porque el celular no usa energía"}]},"solucion":{"valor":false,"explicacion":"Puede ahorrar un poco de batería en algunas pantallas, pero su efecto es mínimo comparado con usar el celular más años.","clave":["r1"]}},{"slug":"digital-1.s5.p13","orden":13,"grupo":"digital-1.s5.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan digital de una familia y marcá lo que casi no ayuda o empeora.","segmentos":[{"id":"s1","texto":"Vamos a usar los celulares hasta que no den más."},{"id":"s2","texto":"Vamos a borrar los mails todos los días para salvar el planeta, y cambiar los celulares cada año."},{"id":"s3","texto":"Vamos a apagar la consola del todo cuando no se usa."},{"id":"s4","texto":"Vamos a comprar un televisor más para cada cuarto."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan digital pone primero lo que más pesa.","por_opcion":{"s2":"Borrar mails casi no ayuda, y cambiar los celulares cada año aumenta mucho la huella.","s4":"Más aparatos es más huella de fabricación y de uso."}}},{"slug":"digital-1.s5.p14","orden":14,"grupo":"digital-1.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Lo que más pesa en la huella digital personal es cuánto {{0}} los dispositivos; borrar mails tiene un efecto muy {{1}}.","banco":[{"id":"w1","texto":"duran"},{"id":"w2","texto":"chico"},{"id":"w3","texto":"cuestan"},{"id":"w4","texto":"grande"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La regla para ordenar los hábitos digitales."}}]},{"slug":"digital-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: la huella de lo digital","bajada_es":"Infraestructura, energía, dispositivos, basura electrónica y hábitos, mezclados.","minutos":8,"pasos":[{"slug":"digital-1.s6.p1","orden":1,"grupo":"digital-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «La huella de lo digital». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"digital-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la casa conectada de los Romero","bajada_es":"Los Romero quieren bajar su huella digital. Con los números, ordená qué hacer primero.","minutos":10,"pasos":[{"slug":"digital-1.s7.p1","orden":1,"grupo":"digital-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La casa","cuerpo":["Los Romero son cuatro. Cada uno cambia el celular cada dos años. Tienen tres televisores, una consola que queda en modo de encendido rápido (15 W, 20 horas por día), un cajón con cinco celulares viejos y dos notebooks rotas. Miran unas 4 horas de video por día entre todos.","Supongamos que fabricar un celular emite 70 kg de CO₂e."]},"solucion":{}},{"slug":"digital-1.s7.p2","orden":2,"grupo":"digital-1.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kg de CO₂e por año suma la fabricación de los celulares, si cada uno de los cuatro cambia el suyo cada dos años?","unidad":"kg CO₂e por año","decimales":0,"contexto":"4 personas, cambian el celular cada 2 años; 70 kg de CO₂e por celular."},"solucion":{"valor":140,"tolerancia":2.8000000000000003,"explicacion":"4 celulares × 70 kg ÷ 2 años = 140 kg por año solo en fabricar celulares nuevos."}},{"slug":"digital-1.s7.p3","orden":3,"grupo":"digital-1.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Y si cada uno lo usara 4 años?","unidad":"kg CO₂e por año","decimales":0,"contexto":"Los mismos 4 celulares, usados 4 años cada uno."},"solucion":{"valor":70,"tolerancia":1.4000000000000001,"explicacion":"4 × 70 ÷ 4 = 70 kg por año: la mitad, solo con usar los celulares más tiempo."}},{"slug":"digital-1.s7.p4","orden":4,"grupo":"digital-1.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kWh por año usa la consola en modo de encendido rápido? Redondeá al entero.","unidad":"kWh","decimales":0,"contexto":"Consola: 15 W, 20 horas por día en encendido rápido."},"solucion":{"valor":110,"tolerancia":1,"explicacion":"0,015 kW × 20 h × 365 ≈ 110 kWh por año sin usarla. Apagarla del todo evita casi todo."}},{"slug":"digital-1.s7.p5","orden":5,"grupo":"digital-1.s7.p5","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas por impacto, de mayor a menor.","items":[{"id":"i1","texto":"Usar los celulares 4 años en vez de 2"},{"id":"i2","texto":"Apagar del todo la consola"},{"id":"i3","texto":"Llevar los celulares y notebooks viejos a reciclar"},{"id":"i4","texto":"Borrar los mails de todos"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero la vida útil de los aparatos, después el stand-by y el destino final. Los mails, al final.","valores":{"i1":"ahorra ≈ 70 kg CO₂e por año","i2":"ahorra ≈ 110 kWh por año","i3":"evita contaminación y recupera metales","i4":"efecto muy chico"}}},{"slug":"digital-1.s7.p6","orden":6,"grupo":"digital-1.s7.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conviene hacer con los cinco celulares viejos del cajón?","opciones":[{"id":"o1","texto":"Donar los que funcionan y llevar el resto a reciclar"},{"id":"o2","texto":"Dejarlos en el cajón por si algún día sirven"},{"id":"o3","texto":"Tirarlos con la basura común"},{"id":"o4","texto":"Quemarlos para recuperar metales"}]},"solucion":{"clave":["o1"],"explicacion":"En un cajón no sirven a nadie. Donados o reciclados, sí.","por_opcion":{"o3":"Tienen baterías que pueden incendiarse y sustancias peligrosas."}}},{"slug":"digital-1.s7.p7","orden":7,"grupo":"digital-1.s7.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las propuestas de la familia.","grupos":[{"id":"g1","nombre":"Ayudan"},{"id":"g2","nombre":"No ayudan o empeoran"}],"items":[{"id":"i1","texto":"Cambiar la batería del celular de la abuela"},{"id":"i2","texto":"Comprar un cuarto televisor para la cocina"},{"id":"i3","texto":"Desenchufar el televisor del cuarto que casi no se usa"},{"id":"i4","texto":"Guardar los aparatos rotos en el cajón"},{"id":"i5","texto":"Llevar las notebooks rotas a un punto de RAEE"},{"id":"i6","texto":"Cambiar todos los celulares por el último modelo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Menos aparatos, más años de uso, menos stand-by y buen destino final."}},{"slug":"digital-1.s7.p8","orden":8,"grupo":"digital-1.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Los Romero escriben su plan. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Vamos a usar los celulares al menos 4 años."},{"id":"s2","texto":"Como miramos 4 horas de video por día, es lo que más contamina en casa: vamos a dejar de mirar."},{"id":"s3","texto":"Llevamos los celulares viejos a un punto de recolección, con los datos borrados."},{"id":"s4","texto":"Dejamos la consola en encendido rápido para que arranque antes."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un plan digital eficaz empieza por lo que más pesa.","por_opcion":{"s2":"4 horas de video son unos 144 g por día: mucho menos que la fabricación de los celulares.","s4":"Consume unos 110 kWh por año sin usarse."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"digital-2","rama":"digital","orden":2,"nivel":1,"titulo_es":"Tecnología que ayuda","bajada_es":"Satélites que detectan incendios, sensores que miden el aire y apps que suman a la ciencia: lo que la tecnología hace por el ambiente, y lo que no puede hacer.","objetivos_es":["Describir cómo los satélites ayudan a vigilar bosques, incendios, agua y hielo","Explicar el valor de los sensores y los datos abiertos","Participar de proyectos de ciencia ciudadana con buenos registros","Reconocer cómo la tecnología ayuda a usar mejor la energía","Evaluar los límites de la tecnología: efecto rebote, brecha digital y tecnosolucionismo"],"repasa":["digital-1","tronco-1"],"requiere_tronco":1,"fuentes":["global-forest-watch","nasa-firms","conae","argentinat","ebird","gbif","iea-eficiencia"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"digital-2.s1","orden":1,"tipo":"leccion","titulo_es":"El planeta visto desde el espacio","bajada_es":"Satélites que detectan desmontes, incendios, glaciares que retroceden y suelos húmedos o secos.","minutos":12,"pasos":[{"slug":"digital-2.s1.p1","orden":1,"grupo":"digital-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ojos en órbita","cuerpo":["Cientos de satélites observan la Tierra todos los días. Con sus imágenes se puede ver dónde se desmontó un bosque, dónde hay un incendio activo, cómo retrocede un glaciar, cuánta agua tiene una laguna o qué tan húmedo está el suelo.","Muchos de esos datos son abiertos y gratuitos: cualquiera puede consultarlos en internet. Eso permitió que organizaciones, periodistas y vecinos vigilen lo que antes solo veían los gobiernos."]},"solucion":{}},{"slug":"digital-2.s1.p2","orden":2,"grupo":"digital-2.s1.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué se puede observar con satélites? Marcá todo.","opciones":[{"id":"o1","texto":"Desmontes de bosques"},{"id":"o2","texto":"Incendios activos"},{"id":"o3","texto":"Retroceso de glaciares"},{"id":"o4","texto":"Superficie de lagunas y humedales"},{"id":"o5","texto":"Qué especie de pájaro canta en tu plaza"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los satélites ven cambios de superficie grandes. Para las especies, hacen falta observaciones en el terreno."}},{"slug":"digital-2.s1.p3","orden":3,"grupo":"digital-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Incendios en tiempo casi real","cuerpo":["Sistemas como FIRMS, de la NASA, detectan focos de calor desde satélites y publican su ubicación en pocas horas. Brigadistas, investigadores y periodistas los usan para seguir incendios, como los de los humedales del Delta del Paraná en 2020, 2022 y 2023.","También se usan imágenes posteriores para medir cuántas hectáreas se quemaron."]},"solucion":{}},{"slug":"digital-2.s1.p4","orden":4,"grupo":"digital-2.s1.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un satélite ayuda a combatir un incendio.","items":[{"id":"i1","texto":"Un satélite detecta un foco de calor anómalo"},{"id":"i2","texto":"El sistema publica su ubicación en pocas horas"},{"id":"i3","texto":"Las brigadas ven el foco en el mapa"},{"id":"i4","texto":"Llegan antes al lugar"},{"id":"i5","texto":"Es más fácil controlar el fuego mientras es chico"},{"id":"i6","texto":"El satélite apaga el fuego desde el espacio"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Detectar temprano es clave: un incendio chico es mucho más fácil de controlar."}},{"slug":"digital-2.s1.p5","orden":5,"grupo":"digital-2.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Bosques y desmontes","cuerpo":["Plataformas como Global Forest Watch muestran, a partir de imágenes satelitales, dónde se perdió cobertura forestal año a año, y emiten alertas casi semanales de desmontes. En el Gran Chaco, uno de los lugares con mayor pérdida de bosques del mundo, estas herramientas permiten ver desmontes incluso en zonas donde la ley no los permite."]},"solucion":{}},{"slug":"digital-2.s1.p6","orden":6,"grupo":"digital-2.s1.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué permite hacer una plataforma de alertas de desmonte con imágenes satelitales?","opciones":[{"id":"o1","texto":"Ver dónde y cuándo se pierde bosque, casi en tiempo real"},{"id":"o2","texto":"Plantar árboles automáticamente desde el espacio"},{"id":"o3","texto":"Castigar a los responsables sin ninguna investigación"},{"id":"o4","texto":"Saber cuántos pájaros hay en cada árbol"}]},"solucion":{"clave":["o1"],"explicacion":"La imagen es evidencia. Transformarla en protección requiere controles, leyes y decisiones.","por_opcion":{"o3":"Las imágenes muestran el cambio; después hacen falta controles en el terreno y la ley."}}},{"slug":"digital-2.s1.p7","orden":7,"grupo":"digital-2.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Satélites argentinos","cuerpo":["Argentina tiene su propia agencia espacial, la CONAE, que desarrolló satélites de observación de la Tierra. Los satélites SAOCOM usan un radar que \"ve\" a través de las nubes y de noche, y miden la humedad del suelo: esos mapas sirven para planificar la agricultura, anticipar inundaciones y seguir sequías."]},"solucion":{}},{"slug":"digital-2.s1.p8","orden":8,"grupo":"digital-2.s1.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada herramienta con lo que observa.","izquierda":[{"id":"a1","texto":"FIRMS (NASA)"},{"id":"a2","texto":"Global Forest Watch"},{"id":"a3","texto":"SAOCOM (CONAE)"},{"id":"a4","texto":"Imágenes de glaciares en distintos años"}],"derecha":[{"id":"b1","texto":"Focos de incendios activos"},{"id":"b2","texto":"Pérdida de bosques y alertas de desmonte"},{"id":"b3","texto":"Humedad del suelo con radar"},{"id":"b4","texto":"Retroceso del hielo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Distintas herramientas para distintas preguntas sobre el planeta."}},{"slug":"digital-2.s1.p9","orden":9,"grupo":"digital-2.s1.p9","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un radar satelital como el de los SAOCOM no puede observar cuando hay nubes.","razones":[{"id":"r1","texto":"Porque el radar emite su propia señal que atraviesa las nubes"},{"id":"r2","texto":"Porque los radares solo funcionan de día"},{"id":"r3","texto":"Porque las nubes reflejan el radar hacia el espacio"}]},"solucion":{"valor":false,"explicacion":"El radar emite su propia señal y la atraviesa por las nubes, de día y de noche. Por eso es muy útil en temporadas de lluvias.","clave":["r1"]}},{"slug":"digital-2.s1.p10","orden":10,"grupo":"digital-2.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un satélite muestra que se quemaron 5.000 hectáreas de humedal. Si una cancha de fútbol tiene unas 0,7 hectáreas, ¿a cuántas canchas equivale? Redondeá al entero.","unidad":"canchas","decimales":0},"solucion":{"valor":7143,"tolerancia":2,"explicacion":"5.000 ÷ 0,7 ≈ 7.143 canchas. Traducir hectáreas a algo conocido ayuda a dimensionar."}},{"slug":"digital-2.s1.p10.v2","orden":10,"grupo":"digital-2.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un satélite muestra que se quemaron 12.000 hectáreas de humedal. Si una cancha de fútbol tiene unas 0,7 hectáreas, ¿a cuántas canchas equivale? Redondeá al entero.","unidad":"canchas","decimales":0},"solucion":{"valor":17143,"tolerancia":2,"explicacion":"12.000 ÷ 0,7 ≈ 17.143 canchas. Traducir hectáreas a algo conocido ayuda a dimensionar."}},{"slug":"digital-2.s1.p10.v3","orden":10,"grupo":"digital-2.s1.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un satélite muestra que se quemaron 800 hectáreas de humedal. Si una cancha de fútbol tiene unas 0,7 hectáreas, ¿a cuántas canchas equivale? Redondeá al entero.","unidad":"canchas","decimales":0},"solucion":{"valor":1143,"tolerancia":2,"explicacion":"800 ÷ 0,7 ≈ 1.143 canchas. Traducir hectáreas a algo conocido ayuda a dimensionar."}},{"slug":"digital-2.s1.p11","orden":11,"grupo":"digital-2.s1.p11","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta pregunta se responde bien con satélites o necesita trabajo en el terreno?","grupos":[{"id":"g1","nombre":"Satélite"},{"id":"g2","nombre":"Terreno"}],"items":[{"id":"i1","texto":"¿Cuántas hectáreas se desmontaron este año?"},{"id":"i2","texto":"¿Qué especies de ranas viven en esta laguna?"},{"id":"i3","texto":"¿Dónde hay focos de incendio ahora?"},{"id":"i4","texto":"¿Qué contaminantes tiene el agua del arroyo?"},{"id":"i5","texto":"¿Cuánto retrocedió un glaciar en diez años?"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Satélites y trabajo en el terreno se complementan: uno ve lo grande, el otro lo fino."}},{"slug":"digital-2.s1.p12","orden":12,"grupo":"digital-2.s1.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas herramientas según qué tan rápido informan un cambio, de más rápida a más lenta.","items":[{"id":"i1","texto":"Detección de focos de incendio"},{"id":"i2","texto":"Alertas de desmonte"},{"id":"i3","texto":"Mapas de pérdida de bosque"},{"id":"i4","texto":"Comparación de glaciares"}],"extremos":["Más rápida","Más lenta"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada fenómeno tiene su ritmo: un incendio se mide en horas; un glaciar, en años.","valores":{"i1":"en horas","i2":"semanales","i3":"anuales","i4":"entre años o décadas"}}},{"slug":"digital-2.s1.p13","orden":13,"grupo":"digital-2.s1.p13","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los datos de los satélites de observación de la Tierra son siempre secretos y pagos.","razones":[{"id":"r1","texto":"Porque muchos son abiertos y gratuitos"},{"id":"r2","texto":"Porque los satélites no generan datos"},{"id":"r3","texto":"Porque solo los militares pueden ver imágenes satelitales"}]},"solucion":{"valor":false,"explicacion":"Muchos son abiertos y gratuitos, como los de FIRMS o los mapas de Global Forest Watch. Eso permite que cualquiera los use para vigilar el ambiente.","clave":["r1"]}},{"slug":"digital-2.s1.p14","orden":14,"grupo":"digital-2.s1.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los satélites pueden detectar focos de incendio."},{"id":"s2","texto":"Si un satélite detecta un desmonte, el problema se resuelve solo."},{"id":"s3","texto":"Muchos datos satelitales son abiertos y gratuitos."},{"id":"s4","texto":"Con un satélite se sabe qué especies de insectos hay en un campo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los satélites son poderosos, pero no lo resuelven todo.","por_opcion":{"s2":"La imagen es evidencia; hacen falta controles y aplicar la ley.","s4":"Eso requiere observaciones en el terreno."}}},{"slug":"digital-2.s1.p15","orden":15,"grupo":"digital-2.s1.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los satélites detectan focos de {{0}} y {{1}}; los SAOCOM argentinos miden la humedad del {{2}}.","banco":[{"id":"w1","texto":"incendio"},{"id":"w2","texto":"desmontes"},{"id":"w3","texto":"suelo"},{"id":"w4","texto":"lluvia"},{"id":"w5","texto":"terremotos"},{"id":"w6","texto":"mar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres usos de los satélites para el ambiente."}}]},{"slug":"digital-2.s2","orden":2,"tipo":"leccion","titulo_es":"Sensores y datos abiertos","bajada_es":"Estaciones meteorológicas, sensores de aire y agua, y por qué los datos abiertos cambian las reglas.","minutos":11,"pasos":[{"slug":"digital-2.s2.p1","orden":1,"grupo":"digital-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Medir en todos lados","cuerpo":["Además de los satélites, hay redes de sensores en el terreno: estaciones meteorológicas que miden lluvia, temperatura y viento; sensores de calidad del aire; medidores del nivel de los ríos; boyas en el mar. Juntos permiten pronosticar el tiempo, alertar crecidas y seguir la contaminación.","Los sensores de bajo costo hicieron posible que escuelas y vecinos midan su propio aire o su propia lluvia, como viste en la rama de Aire y Suelo."]},"solucion":{}},{"slug":"digital-2.s2.p2","orden":2,"grupo":"digital-2.s2.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada sensor con lo que mide.","izquierda":[{"id":"a1","texto":"Pluviómetro"},{"id":"a2","texto":"Sensor de PM2,5"},{"id":"a3","texto":"Limnímetro"},{"id":"a4","texto":"Anemómetro"}],"derecha":[{"id":"b1","texto":"Lluvia"},{"id":"b2","texto":"Partículas finas en el aire"},{"id":"b3","texto":"Nivel del agua de un río"},{"id":"b4","texto":"Velocidad del viento"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada instrumento responde una pregunta concreta."}},{"slug":"digital-2.s2.p3","orden":3,"grupo":"digital-2.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Datos abiertos","cuerpo":["Los datos abiertos son datos que cualquiera puede consultar, descargar y usar libremente. Muchos organismos publican datos ambientales abiertos: emisiones, calidad del agua, lluvias, caudales, áreas protegidas.","En Argentina, la Ley 25.831 garantiza el derecho de acceso a la información pública ambiental. Cuando los datos son abiertos, más personas pueden analizarlos, detectar problemas y controlar a quienes toman decisiones."]},"solucion":{}},{"slug":"digital-2.s2.p4","orden":4,"grupo":"digital-2.s2.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo los datos abiertos pueden mejorar una política ambiental.","items":[{"id":"i1","texto":"Un organismo publica los datos de calidad del agua de un río"},{"id":"i2","texto":"Periodistas e investigadores los analizan"},{"id":"i3","texto":"Detectan un punto que empeora año a año"},{"id":"i4","texto":"Lo difunden y los vecinos piden explicaciones"},{"id":"i5","texto":"El organismo investiga y toma medidas"},{"id":"i6","texto":"Los datos abiertos arreglan el río automáticamente"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La transparencia multiplica los ojos que miran. Es una herramienta de control ciudadano."}},{"slug":"digital-2.s2.p5","orden":5,"grupo":"digital-2.s2.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los datos ambientales públicos solo pueden usarlos los organismos del Estado.","razones":[{"id":"r1","texto":"Porque la ley garantiza el acceso a la información ambiental"},{"id":"r2","texto":"Porque los datos ambientales son secretos por ley"},{"id":"r3","texto":"Porque solo los científicos pueden leer datos"}]},"solucion":{"valor":false,"explicacion":"La Ley 25.831 garantiza el acceso a la información pública ambiental. Los datos abiertos pueden usarlos cualquier persona, escuela u organización.","clave":["r1"]}},{"slug":"digital-2.s2.p6","orden":6,"grupo":"digital-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Calidad de los datos","cuerpo":["No todos los datos valen lo mismo. Un sensor sin calibrar, mal ubicado o sin mantenimiento puede dar números equivocados. Por eso los datos buenos vienen con información sobre cómo se midieron: dónde, cuándo, con qué instrumento y con qué precisión. Esa información se llama metadatos."]},"solucion":{}},{"slug":"digital-2.s2.p7","orden":7,"grupo":"digital-2.s2.p7","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué información debería acompañar a un conjunto de datos para confiar en él? Marcá todo.","opciones":[{"id":"o1","texto":"Dónde se midió"},{"id":"o2","texto":"Cuándo se midió"},{"id":"o3","texto":"Con qué instrumento"},{"id":"o4","texto":"Qué precisión tiene"},{"id":"o5","texto":"Quién tiene más seguidores en redes"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los metadatos permiten saber si un dato sirve para lo que se quiere usar."}},{"slug":"digital-2.s2.p8","orden":8,"grupo":"digital-2.s2.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este sensor está bien ubicado o mal ubicado?","grupos":[{"id":"g1","nombre":"Bien ubicado"},{"id":"g2","nombre":"Mal ubicado"}],"items":[{"id":"i1","texto":"Termómetro a la sombra, en un abrigo ventilado"},{"id":"i2","texto":"Termómetro al sol sobre una chapa"},{"id":"i3","texto":"Pluviómetro en un lugar abierto, lejos de árboles"},{"id":"i4","texto":"Pluviómetro debajo de un árbol"},{"id":"i5","texto":"Sensor de aire a la altura de las personas"},{"id":"i6","texto":"Sensor de aire pegado al caño de escape de un generador"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La ubicación puede arruinar la medición del mejor instrumento. Es el error sistemático de la rama de Ciencia."}},{"slug":"digital-2.s2.p9","orden":9,"grupo":"digital-2.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pluviómetro escolar registró en una semana: 12, 0, 35, 8, 0, 20, 5 mm. ¿Cuántos mm llovieron en total?","unidad":"mm","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"12 + 0 + 35 + 8 + 0 + 20 + 5 = 80 mm. Cada milímetro equivale a un litro por metro cuadrado."}},{"slug":"digital-2.s2.p9.v2","orden":9,"grupo":"digital-2.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pluviómetro escolar registró en una semana: 0, 4, 0, 60, 2, 0, 14 mm. ¿Cuántos mm llovieron en total?","unidad":"mm","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"0 + 4 + 0 + 60 + 2 + 0 + 14 = 80 mm. Cada milímetro equivale a un litro por metro cuadrado."}},{"slug":"digital-2.s2.p9.v3","orden":9,"grupo":"digital-2.s2.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pluviómetro escolar registró en una semana: 25, 18, 0, 0, 3, 40, 9 mm. ¿Cuántos mm llovieron en total?","unidad":"mm","decimales":0},"solucion":{"valor":95,"tolerancia":1.9000000000000001,"explicacion":"25 + 18 + 0 + 0 + 3 + 40 + 9 = 95 mm. Cada milímetro equivale a un litro por metro cuadrado."}},{"slug":"digital-2.s2.p10","orden":10,"grupo":"digital-2.s2.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un municipio quiere saber si el aire de un barrio mejoró. ¿Qué es lo más importante del sensor?","opciones":[{"id":"o1","texto":"Medir siempre en el mismo lugar y con el mismo método"},{"id":"o2","texto":"Que tenga una pantalla de colores"},{"id":"o3","texto":"Moverlo cada semana a un lugar distinto"},{"id":"o4","texto":"Que lo instale la persona con más seguidores"}]},"solucion":{"clave":["o1"],"explicacion":"Para comparar en el tiempo, hay que mantener constantes el lugar y el método.","por_opcion":{"o3":"Si cambia el lugar, no se puede saber si cambió el aire o cambió la ubicación."}}},{"slug":"digital-2.s2.p11","orden":11,"grupo":"digital-2.s2.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe barrial y marcá lo problemático.","segmentos":[{"id":"s1","texto":"Instalamos un pluviómetro en la terraza, lejos de paredes."},{"id":"s2","texto":"El termómetro lo pusimos sobre la chapa del techo para que tome bien el sol."},{"id":"s3","texto":"Publicamos los datos con fecha, lugar e instrumento."},{"id":"s4","texto":"No anotamos cuándo cambiamos las pilas del sensor, no importa."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Datos buenos: bien medidos y bien documentados.","por_opcion":{"s2":"Al sol marca más que la temperatura del aire: es un error sistemático.","s4":"Los cambios en el instrumento son metadatos importantes para interpretar los datos."}}},{"slug":"digital-2.s2.p12","orden":12,"grupo":"digital-2.s2.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los datos que cualquiera puede usar se llaman datos {{0}}; la información sobre cómo se midieron se llama {{1}}.","banco":[{"id":"w1","texto":"abiertos"},{"id":"w2","texto":"metadatos"},{"id":"w3","texto":"cerrados"},{"id":"w4","texto":"rumores"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos conceptos para usar bien los datos ambientales."}},{"slug":"digital-2.s2.p13","orden":13,"grupo":"digital-2.s2.p13","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos litros de agua caen sobre un metro cuadrado con una lluvia de 20 mm.","min":1,"max":200,"paso":1,"unidad":"litros","escala":"lineal"},"solucion":{"valor":20,"banda":"lineal","explicacion":"Un milímetro de lluvia es un litro por metro cuadrado: 20 mm son 20 litros en cada metro cuadrado."}}]},{"slug":"digital-2.s3","orden":3,"tipo":"leccion","titulo_es":"Ciencia ciudadana con el celular","bajada_es":"Fotos de especies, registros de aves y reportes ambientales: cómo cualquiera puede aportar datos útiles a la ciencia.","minutos":11,"pasos":[{"slug":"digital-2.s3.p1","orden":1,"grupo":"digital-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es la ciencia ciudadana","cuerpo":["La ciencia ciudadana es la participación de personas no especialistas en investigaciones científicas: contar aves, fotografiar plantas e insectos, medir la lluvia, reportar la calidad del agua. Con millones de participantes se reúnen datos que ningún equipo científico podría juntar solo.","En Argentina, plataformas como ArgentiNat (la versión local de iNaturalist) y eBird reúnen cientos de miles de observaciones que usan investigadores y organismos de conservación. Muchas terminan en bases de datos globales como GBIF."]},"solucion":{}},{"slug":"digital-2.s3.p2","orden":2,"grupo":"digital-2.s3.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada plataforma con lo que se registra en ella.","izquierda":[{"id":"a1","texto":"ArgentiNat"},{"id":"a2","texto":"eBird"},{"id":"a3","texto":"GBIF"}],"derecha":[{"id":"b1","texto":"Fotos de cualquier ser vivo con su ubicación"},{"id":"b2","texto":"Listas de aves observadas"},{"id":"b3","texto":"Base global que reúne registros de biodiversidad"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Tres herramientas conectadas: los registros locales alimentan bases globales."}},{"slug":"digital-2.s3.p3","orden":3,"grupo":"digital-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un buen registro","cuerpo":["Para que una observación sirva a la ciencia necesita: una foto nítida (o varias, de distintos ángulos), la fecha, la ubicación precisa y, si se puede, una nota sobre el ambiente. En ArgentiNat, otras personas —incluidas especialistas— ayudan a identificar la especie; cuando varias coinciden, el registro pasa a \"grado de investigación\".","Un registro sin ubicación o con una foto borrosa casi no sirve, aunque la especie sea rara."]},"solucion":{}},{"slug":"digital-2.s3.p4","orden":4,"grupo":"digital-2.s3.p4","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace útil un registro de ciencia ciudadana? Marcá todo.","opciones":[{"id":"o1","texto":"Foto nítida"},{"id":"o2","texto":"Fecha"},{"id":"o3","texto":"Ubicación precisa"},{"id":"o4","texto":"Nota sobre el ambiente"},{"id":"o5","texto":"Un filtro de colores en la foto"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los filtros pueden cambiar los colores y dificultar la identificación."}},{"slug":"digital-2.s3.p5","orden":5,"grupo":"digital-2.s3.p5","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para subir un buen registro a ArgentiNat.","items":[{"id":"i1","texto":"Encontrar un ser vivo sin molestarlo"},{"id":"i2","texto":"Sacar varias fotos nítidas desde distintos ángulos"},{"id":"i3","texto":"Registrar fecha y ubicación"},{"id":"i4","texto":"Subirlo con una identificación tentativa"},{"id":"i5","texto":"Esperar que la comunidad confirme la especie"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Observar sin molestar, documentar bien y dejar que la comunidad ayude a identificar."}},{"slug":"digital-2.s3.p6","orden":6,"grupo":"digital-2.s3.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una foto en tu patio puede ayudar a la conservación.","items":[{"id":"i1","texto":"Fotografiás una rana en tu patio y la subís con ubicación"},{"id":"i2","texto":"La comunidad confirma que es una especie amenazada"},{"id":"i3","texto":"El registro llega a bases de datos de biodiversidad"},{"id":"i4","texto":"Investigadores descubren que hay una población en tu zona"},{"id":"i5","texto":"Se pueden tomar medidas para proteger ese ambiente"},{"id":"i6","texto":"La foto hace que la rana deje de estar amenazada"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Muchos descubrimientos empezaron con un registro de alguien no especialista."}},{"slug":"digital-2.s3.p7","orden":7,"grupo":"digital-2.s3.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los datos de ciencia ciudadana no sirven porque no los toman especialistas.","razones":[{"id":"r1","texto":"Porque con buenos registros y verificación se usan en investigaciones"},{"id":"r2","texto":"Porque los especialistas no revisan nunca los datos"},{"id":"r3","texto":"Porque solo sirven los datos de satélites"}]},"solucion":{"valor":false,"explicacion":"Con buenos registros y verificación de la comunidad, se usan en investigaciones publicadas y en decisiones de conservación. La cantidad y la cobertura compensan muchas limitaciones.","clave":["r1"]}},{"slug":"digital-2.s3.p8","orden":8,"grupo":"digital-2.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuidar lo que se observa","cuerpo":["Observar no debe dañar: no se sacan animales de su lugar para fotografiarlos, no se acercan a nidos, no se pisotean plantas. En especies muy amenazadas o buscadas por el tráfico, las plataformas pueden ocultar la ubicación exacta para protegerlas."]},"solucion":{}},{"slug":"digital-2.s3.p9","orden":9,"grupo":"digital-2.s3.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta práctica es correcta o incorrecta al hacer ciencia ciudadana?","grupos":[{"id":"g1","nombre":"Correcta"},{"id":"g2","nombre":"Incorrecta"}],"items":[{"id":"i1","texto":"Fotografiar un ave desde lejos con zoom"},{"id":"i2","texto":"Mover un sapo a un lugar más lindo para la foto"},{"id":"i3","texto":"Registrar una planta sin arrancarla"},{"id":"i4","texto":"Acercarse a un nido para una mejor toma"},{"id":"i5","texto":"Ocultar la ubicación de una especie buscada por traficantes"},{"id":"i6","texto":"Arrancar una flor para fotografiarla en casa"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La ciencia ciudadana suma datos sin restar naturaleza."}},{"slug":"digital-2.s3.p10","orden":10,"grupo":"digital-2.s3.p10","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Encontrás un ave rara y querés registrarla. ¿Qué es lo más importante?","opciones":[{"id":"o1","texto":"Una foto nítida con fecha y ubicación, sin molestarla"},{"id":"o2","texto":"Acercarte lo más posible aunque se asuste"},{"id":"o3","texto":"Esperar a que vuelva otro día para estar seguro"},{"id":"o4","texto":"Compartirla solo en tus redes sin ubicación"}]},"solucion":{"clave":["o1"],"explicacion":"Un buen registro, hecho con respeto, es el aporte.","por_opcion":{"o3":"Registrá lo que viste ahora: un registro bien documentado ya es valioso."}}},{"slug":"digital-2.s3.p11","orden":11,"grupo":"digital-2.s3.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un censo de aves, 500 personas hacen 20 registros cada una. ¿Cuántos registros se juntan?","unidad":"registros","decimales":0},"solucion":{"valor":10000,"tolerancia":200,"explicacion":"500 × 20 = 10.000 registros. Ningún equipo científico podría juntar tantos por su cuenta."}},{"slug":"digital-2.s3.p11.v2","orden":11,"grupo":"digital-2.s3.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un censo de aves, 1.000 personas hacen 15 registros cada una. ¿Cuántos registros se juntan?","unidad":"registros","decimales":0},"solucion":{"valor":15000,"tolerancia":300,"explicacion":"1.000 × 15 = 15.000 registros. Ningún equipo científico podría juntar tantos por su cuenta."}},{"slug":"digital-2.s3.p11.v3","orden":11,"grupo":"digital-2.s3.p11","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un censo de aves, 200 personas hacen 50 registros cada una. ¿Cuántos registros se juntan?","unidad":"registros","decimales":0},"solucion":{"valor":10000,"tolerancia":200,"explicacion":"200 × 50 = 10.000 registros. Ningún equipo científico podría juntar tantos por su cuenta."}},{"slug":"digital-2.s3.p12","orden":12,"grupo":"digital-2.s3.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo de un grupo de observadores y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Registrá fecha y ubicación en cada observación."},{"id":"s2","texto":"Si el ave está lejos, tirale una piedra cerca para que se mueva."},{"id":"s3","texto":"Dejá que la comunidad ayude con la identificación."},{"id":"s4","texto":"Si no estás seguro de la especie, no lo subas nunca."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Registros buenos y respetuosos: la base de la ciencia ciudadana.","por_opcion":{"s2":"Nunca se molesta a la fauna para una foto.","s4":"Se puede subir con una identificación tentativa: la comunidad ayuda."}}},{"slug":"digital-2.s3.p13","orden":13,"grupo":"digital-2.s3.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La participación de personas no especialistas en investigaciones se llama ciencia {{0}}; un buen registro necesita foto, fecha y {{1}}.","banco":[{"id":"w1","texto":"ciudadana"},{"id":"w2","texto":"ubicación"},{"id":"w3","texto":"privada"},{"id":"w4","texto":"filtro"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La idea central de la lección, resumida en una línea."}}]},{"slug":"digital-2.s4","orden":4,"tipo":"leccion","titulo_es":"Energía inteligente","bajada_es":"Medidores inteligentes, termostatos, gestión de la demanda y redes que se adaptan a las renovables.","minutos":11,"pasos":[{"slug":"digital-2.s4.p1","orden":1,"grupo":"digital-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ver el consumo en tiempo real","cuerpo":["Los medidores inteligentes registran el consumo de electricidad hora por hora y lo muestran en una app o en la factura. Ver cuándo y en qué se consume ayuda a detectar derroches, como un aparato que queda encendido de noche.","Los termostatos programables apagan o bajan la calefacción cuando no hay nadie, y la encienden un rato antes de volver."]},"solucion":{}},{"slug":"digital-2.s4.p2","orden":2,"grupo":"digital-2.s4.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un medidor inteligente ayuda a ahorrar.","items":[{"id":"i1","texto":"El medidor registra el consumo hora por hora"},{"id":"i2","texto":"La familia ve un consumo alto a las 3 de la mañana"},{"id":"i3","texto":"Descubre un calefactor olvidado en una habitación"},{"id":"i4","texto":"Lo apaga y el consumo nocturno baja"},{"id":"i5","texto":"El medidor apaga solo cualquier aparato"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Ver el consumo es el primer paso para cambiarlo. Medir para entender, como en el tronco."}},{"slug":"digital-2.s4.p3","orden":3,"grupo":"digital-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La demanda y las renovables","cuerpo":["La electricidad tiene que producirse en el mismo momento en que se consume. El sol y el viento no siempre generan cuando más se necesita. Por eso, cada vez más, se busca mover el consumo a los momentos de más generación renovable: cargar un auto eléctrico o calentar agua cuando hay mucho viento o sol.","Eso se llama gestión de la demanda, y la tecnología digital —precios que cambian por hora, aparatos que se encienden solos en el mejor momento— la hace posible."]},"solucion":{}},{"slug":"digital-2.s4.p4","orden":4,"grupo":"digital-2.s4.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es la gestión de la demanda eléctrica?","opciones":[{"id":"o1","texto":"Mover consumos a los momentos en que conviene generar"},{"id":"o2","texto":"Prohibir el uso de electricidad de noche"},{"id":"o3","texto":"Producir siempre la misma cantidad de electricidad"},{"id":"o4","texto":"Cobrar lo mismo sin importar la hora"}]},"solucion":{"clave":["o1"],"explicacion":"Adaptar el consumo a la generación, sobre todo cuando hay mucho sol y viento, ayuda a integrar renovables.","por_opcion":{"o3":"La generación y el consumo cambian; la idea es acercarlos."}}},{"slug":"digital-2.s4.p5","orden":5,"grupo":"digital-2.s4.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este uso se puede mover a otro horario o no conviene moverlo?","grupos":[{"id":"g1","nombre":"Se puede mover"},{"id":"g2","nombre":"No conviene moverlo"}],"items":[{"id":"i1","texto":"Cargar un auto eléctrico"},{"id":"i2","texto":"La heladera"},{"id":"i3","texto":"Calentar agua en un termotanque eléctrico"},{"id":"i4","texto":"La luz de la cocina mientras cocinás"},{"id":"i5","texto":"Poner el lavarropas"},{"id":"i6","texto":"Un respirador médico"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los consumos flexibles son la herramienta de la gestión de la demanda."}},{"slug":"digital-2.s4.p6","orden":6,"grupo":"digital-2.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto eléctrico carga 10 kWh por día. Si el kWh cuesta $150 en horario pico y $90 de madrugada, ¿cuánto se ahorra por día cargando de madrugada?","unidad":"$","decimales":0},"solucion":{"valor":600,"tolerancia":12,"explicacion":"10 × (150 − 90) = $600 por día. Los precios por horario incentivan mover el consumo."}},{"slug":"digital-2.s4.p6.v2","orden":6,"grupo":"digital-2.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto eléctrico carga 15 kWh por día. Si el kWh cuesta $180 en horario pico y $100 de madrugada, ¿cuánto se ahorra por día cargando de madrugada?","unidad":"$","decimales":0},"solucion":{"valor":1200,"tolerancia":24,"explicacion":"15 × (180 − 100) = $1.200 por día. Los precios por horario incentivan mover el consumo."}},{"slug":"digital-2.s4.p6.v3","orden":6,"grupo":"digital-2.s4.p6","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un auto eléctrico carga 8 kWh por día. Si el kWh cuesta $120 en horario pico y $70 de madrugada, ¿cuánto se ahorra por día cargando de madrugada?","unidad":"$","decimales":0},"solucion":{"valor":400,"tolerancia":8,"explicacion":"8 × (120 − 70) = $400 por día. Los precios por horario incentivan mover el consumo."}},{"slug":"digital-2.s4.p7","orden":7,"grupo":"digital-2.s4.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La electricidad se puede producir de sobra un día y guardarla toda en los cables para usarla después.","razones":[{"id":"r1","texto":"Porque los cables transportan pero no almacenan energía"},{"id":"r2","texto":"Porque la electricidad se guarda en los enchufes"},{"id":"r3","texto":"Porque sobra electricidad siempre"}]},"solucion":{"valor":false,"explicacion":"Los cables no guardan energía. Para almacenar hacen falta baterías, represas de bombeo u otros sistemas. Por eso importa acercar el consumo a la generación.","clave":["r1"]}},{"slug":"digital-2.s4.p8","orden":8,"grupo":"digital-2.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Edificios que se regulan solos","cuerpo":["En edificios grandes, sistemas de gestión digital controlan la iluminación, la calefacción y el aire acondicionado según la ocupación, la hora y el clima. Con sensores de presencia y de luz natural, se pueden lograr ahorros importantes sin que nadie tenga que acordarse de apagar nada."]},"solucion":{}},{"slug":"digital-2.s4.p9","orden":9,"grupo":"digital-2.s4.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué tecnologías ayudan a ahorrar energía en un edificio? Marcá todas.","opciones":[{"id":"o1","texto":"Sensores de presencia para las luces"},{"id":"o2","texto":"Termostatos programables"},{"id":"o3","texto":"Medidores inteligentes"},{"id":"o4","texto":"Sensores de luz natural"},{"id":"o5","texto":"Pantallas encendidas las 24 horas en cada pasillo"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La tecnología que mide y controla puede ahorrar mucho. La que suma consumo sin sentido, no."}},{"slug":"digital-2.s4.p10","orden":10,"grupo":"digital-2.s4.p10","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada tecnología con lo que hace.","izquierda":[{"id":"a1","texto":"Medidor inteligente"},{"id":"a2","texto":"Termostato programable"},{"id":"a3","texto":"Sensor de presencia"},{"id":"a4","texto":"Precio por horario"}],"derecha":[{"id":"b1","texto":"Muestra el consumo hora por hora"},{"id":"b2","texto":"Ajusta la calefacción según el horario"},{"id":"b3","texto":"Apaga luces donde no hay nadie"},{"id":"b4","texto":"Incentiva consumir en las mejores horas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro herramientas de la energía inteligente."}},{"slug":"digital-2.s4.p11","orden":11,"grupo":"digital-2.s4.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un medidor inteligente reduce el consumo por sí solo, aunque nadie cambie nada.","razones":[{"id":"r1","texto":"Porque el ahorro depende de lo que se haga con la información"},{"id":"r2","texto":"Porque los medidores apagan toda la casa"},{"id":"r3","texto":"Porque los medidores consumen más de lo que ahorran"}]},"solucion":{"valor":false,"explicacion":"El medidor muestra la información; el ahorro aparece cuando alguien actúa con ella, o cuando se combina con aparatos que se regulan solos.","clave":["r1"]}},{"slug":"digital-2.s4.p12","orden":12,"grupo":"digital-2.s4.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Es un día de mucho viento, la red tiene energía eólica de sobra y el precio está bajo. ¿Qué conviene hacer con un termotanque eléctrico programable?","opciones":[{"id":"o1","texto":"Calentar el agua en ese momento"},{"id":"o2","texto":"Apagarlo hasta que baje el viento"},{"id":"o3","texto":"Esperar al horario pico de la noche"},{"id":"o4","texto":"Desenchufarlo para siempre"}]},"solucion":{"clave":["o1"],"explicacion":"Guardar energía como agua caliente cuando sobra renovable es gestión de la demanda en acción.","por_opcion":{"o3":"En el pico la electricidad es más cara y suele generarse con más gas."}}},{"slug":"digital-2.s4.p13","orden":13,"grupo":"digital-2.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta publicidad y marcá lo exagerado.","segmentos":[{"id":"s1","texto":"Nuestro termostato apaga la calefacción cuando no hay nadie."},{"id":"s2","texto":"Con nuestra app, tu casa no va a consumir energía nunca más."},{"id":"s3","texto":"El medidor te muestra el consumo de cada hora."},{"id":"s4","texto":"Instalar un sensor compensa tener la calefacción a 26 °C todo el día."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La tecnología es una aliada, no una varita mágica.","por_opcion":{"s2":"Puede ayudar a ahorrar, pero la casa sigue consumiendo energía.","s4":"La tecnología ayuda, pero no compensa un hábito que derrocha mucho."}}},{"slug":"digital-2.s4.p14","orden":14,"grupo":"digital-2.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Mover consumos a las horas de más generación se llama gestión de la {{0}}; los medidores {{1}} muestran el consumo por hora.","banco":[{"id":"w1","texto":"demanda"},{"id":"w2","texto":"inteligentes"},{"id":"w3","texto":"oferta"},{"id":"w4","texto":"analógicos"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas clave de la energía inteligente."}}]},{"slug":"digital-2.s5","orden":5,"tipo":"leccion","titulo_es":"Los límites de la tecnología","bajada_es":"Efecto rebote, brecha digital, privacidad y la tentación de creer que la tecnología sola lo resuelve todo.","minutos":12,"pasos":[{"slug":"digital-2.s5.p1","orden":1,"grupo":"digital-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El efecto rebote","cuerpo":["Cuando una tecnología hace algo más eficiente y más barato, a veces se usa tanto más que el ahorro se achica o desaparece. Se llama efecto rebote. Si las lámparas LED gastan poco, puede que se dejen más luces encendidas; si un auto consume menos, puede que se viaje más.","La eficiencia sigue siendo buena, pero hay que acompañarla con hábitos y reglas para que el ahorro se mantenga."]},"solucion":{}},{"slug":"digital-2.s5.p2","orden":2,"grupo":"digital-2.s5.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de un efecto rebote.","items":[{"id":"i1","texto":"Un auto nuevo consume la mitad de nafta"},{"id":"i2","texto":"Viajar en auto se vuelve más barato"},{"id":"i3","texto":"La familia viaja más kilómetros"},{"id":"i4","texto":"Parte del ahorro de nafta se pierde"},{"id":"i5","texto":"El auto eficiente obliga a viajar menos"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La eficiencia ahorra, salvo que el ahorro se \"gaste\" usando más."}},{"slug":"digital-2.s5.p3","orden":3,"grupo":"digital-2.s5.p3","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una tecnología más eficiente siempre reduce el consumo total en la misma proporción.","razones":[{"id":"r1","texto":"Porque el efecto rebote puede aumentar el uso"},{"id":"r2","texto":"Porque las tecnologías eficientes consumen más"},{"id":"r3","texto":"Porque la eficiencia no existe"}]},"solucion":{"valor":false,"explicacion":"Por el efecto rebote, parte del ahorro puede perderse si se usa más. Hace falta acompañar la eficiencia con hábitos y reglas.","clave":["r1"]}},{"slug":"digital-2.s5.p4","orden":4,"grupo":"digital-2.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Brecha digital","cuerpo":["No todas las personas tienen el mismo acceso a la tecnología: conexión, dispositivos, habilidades. Si las soluciones ambientales dependen solo de apps o de aparatos caros, pueden dejar afuera a quienes más necesitan ayuda. Una buena política ambiental piensa también en quienes no tienen acceso."]},"solucion":{}},{"slug":"digital-2.s5.p5","orden":5,"grupo":"digital-2.s5.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un municipio anuncia que las alertas de inundación solo se enviarán por una app. ¿Cuál es el problema?","opciones":[{"id":"o1","texto":"Deja afuera a quienes no tienen celular o conexión"},{"id":"o2","texto":"Las apps no pueden enviar alertas"},{"id":"o3","texto":"Ninguno: todo el mundo tiene la app"},{"id":"o4","texto":"Las inundaciones no se pueden pronosticar"}]},"solucion":{"clave":["o1"],"explicacion":"Las alertas tienen que llegar a todos: sirenas, radio, mensajes de texto y referentes barriales, además de apps.","por_opcion":{"o3":"No todos tienen celular, datos o la app instalada, y a menudo son quienes viven en zonas más expuestas."}}},{"slug":"digital-2.s5.p6","orden":6,"grupo":"digital-2.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tecnosolucionismo","cuerpo":["El tecnosolucionismo es la idea de que cualquier problema se resuelve con una tecnología nueva, sin cambiar hábitos, reglas ni sistemas. Por ejemplo, esperar que una máquina capture todo el CO₂ en lugar de dejar de emitirlo, o que una app resuelva la basura sin separar ni reducir.","La tecnología ayuda mucho, pero casi siempre funciona mejor combinada con cambios de comportamiento, de políticas y de diseño."]},"solucion":{}},{"slug":"digital-2.s5.p7","orden":7,"grupo":"digital-2.s5.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un enfoque equilibrado o tecnosolucionista?","grupos":[{"id":"g1","nombre":"Equilibrado"},{"id":"g2","nombre":"Tecnosolucionista"}],"items":[{"id":"i1","texto":"Sensores de aire más una ley que controle las emisiones"},{"id":"i2","texto":"Seguir emitiendo porque algún día se inventará algo"},{"id":"i3","texto":"Satélites para detectar desmontes más controles en el terreno"},{"id":"i4","texto":"Una app de reciclaje sin sistema de recolección"},{"id":"i5","texto":"Medidores inteligentes más hábitos de ahorro"},{"id":"i6","texto":"Plantar árboles digitales en un juego para compensar un vuelo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La tecnología potencia las soluciones; rara vez las reemplaza."}},{"slug":"digital-2.s5.p8","orden":8,"grupo":"digital-2.s5.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué riesgos tiene confiar todo a la tecnología? Marcá todos.","opciones":[{"id":"o1","texto":"Efecto rebote que se come el ahorro"},{"id":"o2","texto":"Dejar afuera a quienes no tienen acceso"},{"id":"o3","texto":"Postergar cambios necesarios esperando un invento"},{"id":"o4","texto":"Problemas de privacidad con los datos personales"},{"id":"o5","texto":"Que la tecnología funcione demasiado bien"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Reconocer los riesgos permite aprovechar la tecnología sin caer en sus trampas."}},{"slug":"digital-2.s5.p9","orden":9,"grupo":"digital-2.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Privacidad","cuerpo":["Muchas tecnologías inteligentes recolectan datos personales: cuándo estás en tu casa, cuánto consumís, por dónde te movés. Esos datos pueden ayudar a ahorrar, pero también pueden usarse para otras cosas. Conviene saber qué datos recolecta una app o un aparato, quién los usa y para qué."]},"solucion":{}},{"slug":"digital-2.s5.p10","orden":10,"grupo":"digital-2.s5.p10","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para usar una app de energía cuidando tus datos.","items":[{"id":"i1","texto":"Leer qué datos recolecta"},{"id":"i2","texto":"Revisar quién los usa y para qué"},{"id":"i3","texto":"Ajustar los permisos a lo necesario"},{"id":"i4","texto":"Usarla para detectar consumos y ahorrar"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Aprovechar la tecnología con criterio, también sobre la propia información."}},{"slug":"digital-2.s5.p11","orden":11,"grupo":"digital-2.s5.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas soluciones para bajar las emisiones de una ciudad, de la más completa a la más limitada.","items":[{"id":"i1","texto":"Transporte público eléctrico más ciclovías más reglas de estacionamiento"},{"id":"i2","texto":"Colectivos eléctricos sin cambios en la frecuencia"},{"id":"i3","texto":"Una app que calcula tu huella de transporte"},{"id":"i4","texto":"Esperar autos voladores eléctricos"}],"extremos":["Más completa","Más limitada"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las soluciones más completas combinan tecnología con cambios en el sistema.","valores":{"i1":"combina tecnología, diseño y reglas","i2":"tecnología sola, útil","i3":"informa pero no cambia opciones","i4":"tecnosolucionismo"}}},{"slug":"digital-2.s5.p12","orden":12,"grupo":"digital-2.s5.p12","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su ejemplo.","izquierda":[{"id":"a1","texto":"Efecto rebote"},{"id":"a2","texto":"Brecha digital"},{"id":"a3","texto":"Tecnosolucionismo"},{"id":"a4","texto":"Privacidad"}],"derecha":[{"id":"b1","texto":"Con lámparas LED, se dejan más luces prendidas"},{"id":"b2","texto":"Alertas solo por app en barrios sin conexión"},{"id":"b3","texto":"Seguir emitiendo esperando un invento"},{"id":"b4","texto":"Una app que sabe cuándo no hay nadie en casa"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro límites de la tecnología que conviene reconocer en la vida real."}},{"slug":"digital-2.s5.p13","orden":13,"grupo":"digital-2.s5.p13","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia viajaba 10.000 km por año con un auto que gastaba 8 L cada 100 km. Cambia a uno que gasta 4 L cada 100 km y, como sale más barato, pasa a viajar 12.000 km. ¿Cuántos litros de nafta ahorra de verdad por año?","unidad":"litros","decimales":0},"solucion":{"valor":320,"tolerancia":6.4,"explicacion":"Antes: 10.000 × 8 ÷ 100 = 800 L. Ahora: 12.000 × 4 ÷ 100 = 480 L. Ah